 private fun compress(b:Bitmap):ByteArray{val scale=minOf(1f,1600f/maxOf(b.width,b.height));val img=Bitmap.createScaledBitmap(b,maxOf(1,(b.width*scale).toInt()),maxOf(1,(b.height*scale).toInt()),true);return ByteArrayOutputStream().also{img.compress(Bitmap.CompressFormat.JPEG,80,it)}.toByteArray()}
 @Composable fun App(){
 val scope=rememberCoroutineScope();var projects by remember{mutableStateOf(emptyList<Project>())};var project by remember{mutableStateOf("")};var data by remember{mutableStateOf(emptyList<Map<String,String>>())};var page by remember{mutableStateOf("主頁")};var previous by remember{mutableStateOf("戶別搜尋")};var selected by remember{mutableStateOf("")};var preview by remember{mutableStateOf(emptyList<Map<String,String>>())};var photos by remember{mutableStateOf(emptyList<ByteArray>())};var history by remember{mutableStateOf(emptyList<Event>())};var note by remember{mutableStateOf("")};var name by remember{mutableStateOf("")};var msg by remember{mutableStateOf("")};var busy by remember{mutableStateOf(false)};var restoreConfirm by remember{mutableStateOf(false)}
 suspend fun refresh(){val result=withContext(Dispatchers.IO){store.projects()};projects=result;if(projects.none{it.id==project})project=projects.firstOrNull()?.id.orEmpty();val p=project;data=withContext(Dispatchers.IO){store.defects(p).map{decode(it.payload)}};val d=selected;history=withContext(Dispatchers.IO){store.history(p,d)}}
