 BackHandler(page!="主頁"){back()}
 val pick=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){uri->if(uri!=null)run{preview=withContext(Dispatchers.IO){contentResolver.openInputStream(uri)!!.use{Excel.read(it)}};require(preview.isNotEmpty()){ "沒有有效缺失資料" }}}
 val camera=rememberLauncherForActivityResult(ActivityResultContracts.TakePicture()){ok->if(ok)run{val f=File(File(cacheDir,"camera").apply{mkdirs()},"capture.jpg");val bounds=BitmapFactory.Options().apply{inJustDecodeBounds=true};BitmapFactory.decodeFile(f.path,bounds);var sample=1;while(maxOf(bounds.outWidth,bounds.outHeight)/sample>2400)sample*=2;val b=BitmapFactory.decodeFile(f.path,BitmapFactory.Options().apply{inSampleSize=sample});photos=photos+compress(requireNotNull(b));f.delete()}}
 val gallery=rememberLauncherForActivityResult(ActivityResultContracts.GetMultipleContents()){uris:List<Uri>->run{photos=photos+withContext(Dispatchers.IO){uris.map{u->val bounds=BitmapFactory.Options().apply{inJustDecodeBounds=true};contentResolver.openInputStream(u)!!.use{BitmapFactory.decodeStream(it,null,bounds)};var sample=1;while(maxOf(bounds.outWidth,bounds.outHeight)/sample>2400)sample*=2;val b=contentResolver.openInputStream(u)!!.use{BitmapFactory.decodeStream(it,null,BitmapFactory.Options().apply{inSampleSize=sample})};compress(requireNotNull(b){"無法讀取照片"})}}}}
 val export=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")){uri->if(uri!=null)run{val snapshot=data;withContext(Dispatchers.IO){contentResolver.openOutputStream(uri)!!.use{Excel.write(it,reports(snapshot))}};msg="匯出完成"}}
 val backup=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/zip")){uri->if(uri!=null)run{withContext(Dispatchers.IO){contentResolver.openOutputStream(uri)!!.use{Backup.write(db,it)}};msg="備份完成，請妥善保管"}}
 val restore=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){uri->if(uri!=null)run{withContext(Dispatchers.IO){contentResolver.openInputStream(uri)!!.use{Backup.restore(db,it)}};project="";selected="";refresh();page="主頁";msg="還原完成"}}
 fun close(status:String){val row=current?:return;val p=project;val pictures=photos;val memo=note;run{require(status=="未銷單"||pictures.isNotEmpty());withContext(Dispatchers.IO){db.runInTransaction{val ids=pictures.map{b->UUID.randomUUID().toString().also{store.put(Photo(it,b))}};val id=row.getValue("id");store.put(Event(UUID.randomUUID().toString(),p,id,status,java.time.LocalDateTime.now().toString(),memo,JSONArray(ids).toString()));store.put(Defect(p,id,encode(row+mapOf("status" to status,"completed" to if(status=="已銷單")java.time.LocalDate.now().toString() else ""))))}};photos=emptyList();note="";refresh();msg="修繕紀錄已儲存"}}
 Surface(Modifier.fillMaxSize().systemBarsPadding()){Column{Surface(color=MaterialTheme.colorScheme.primary){Column(Modifier.fillMaxWidth().padding(16.dp)){Text("售服缺失銷單系統",style=MaterialTheme.typography.headlineSmall);Text("RepairTrack V3.0 · 離線單機版")}};Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){
 if(busy)LinearProgressIndicator(Modifier.fillMaxWidth());if(msg.isNotBlank())AlertDialog(onDismissRequest={msg=""},confirmButton={TextButton(onClick={msg=""}){Text("確定")}},text={Text(msg)})
 if(restoreConfirm)AlertDialog(onDismissRequest={restoreConfirm=false},title={Text("還原將取代全部本機資料")},text={Text("請先備份現有資料，確認後選擇 ZIP。")},confirmButton={TextButton(onClick={restoreConfirm=false;restore.launch(arrayOf("application/zip","application/octet-stream"))}){Text("確認還原")}},dismissButton={TextButton(onClick={restoreConfirm=false}){Text("取消")}})
 if(page!="主頁")TextButton(onClick={back()}){Text("返回主頁")};Text(page,style=MaterialTheme.typography.titleLarge)
 when(page){
 "主頁"->{Column(Modifier.verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(8.dp)){Drop("目前建案",projects.firstOrNull{it.id==project}?.name?:"尚無建案",projects.map{it.name}){n->run{project=projects.first{it.name==n}.id;refresh()}};Stats(data);listOf("戶別搜尋","工項搜尋","廠商搜尋","缺失統整計算","匯入缺失總表","匯出銷單總表","建案管理","資料備份","還原資料").chunked(3).forEach{group->Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){group.forEach{p->ElevatedCard(onClick={if(!busy){if(project.isBlank()&&p !in listOf("建案管理","還原資料","資料備份")){page="建案管理"}else page=p}},modifier=Modifier.weight(1f).height(90.dp)){Box(Modifier.padding(12.dp)){Text(p)}}}}}}}
 "建案管理"->{OutlinedTextField(name,{name=it},label={Text("建案名稱")});Button(enabled=!busy&&name.isNotBlank(),onClick={run{val n=name.trim();require(projects.none{it.name==n}){"建案名稱已存在"};val p=Project(UUID.randomUUID().toString(),n);withContext(Dispatchers.IO){store.put(p)};project=p.id;name="";refresh()}}){Text("新增建案")};Button(enabled=!busy&&project.isNotBlank()&&name.isNotBlank(),onClick={run{val n=name.trim();require(projects.none{it.name==n&&it.id!=project});withContext(Dispatchers.IO){store.put(Project(project,n))};name="";refresh()}}){Text("重新命名目前建案")};projects.forEach{p->TextButton(onClick={run{project=p.id;refresh();page="主頁"}}){Text(p.name)}}}
 "資料備份"->{Text("備份所有建案、缺失、照片及修繕紀錄。備份含個資，請妥善保管。");Button(enabled=!busy,onClick={backup.launch("RepairTrack_Backup_${java.time.LocalDate.now()}.zip")}){Text("建立 ZIP 備份")}}
 "還原資料"->{Text("還原會取代所有本機資料。");Button(enabled=!busy,onClick={restoreConfirm=true}){Text("選擇備份 ZIP")}}
 "缺失統整計算"->{Stats(data);Text("缺失數最多前三工項");data.groupBy{it["trade"]}.entries.sortedByDescending{it.value.size}.take(3).forEach{Text("${it.key}：${it.value.size} 件")}}
 "匯入缺失總表"->{Button(enabled=!busy,onClick={pick.launch(arrayOf("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"))}){Text("選擇 Excel")};if(preview.isNotEmpty()){val old=data.associateBy{it["id"]};Text("共 ${preview.size} 筆；新增 ${preview.count{it["id"] !in old}} 筆；更新 ${preview.count{it["id"] in old}} 筆");Text("既有狀態及照片保留；缺失文字修改可能產生新筆。");Button(enabled=!busy,onClick={run{val p=project;val rows=preview;withContext(Dispatchers.IO){db.runInTransaction{rows.forEach{r->val id=r.getValue("id");val prior=old[id];val merged=if(prior==null)r else r+prior.filterKeys{it in listOf("status","completed")};store.put(Defect(p,id,encode(merged)))}}};preview=emptyList();refresh();msg="匯入完成"}}){Text("確認更新")}}}
 "匯出銷單總表"->{Stats(data);Button(enabled=!busy,onClick={export.launch("銷單總表.xlsx")}){Text("匯出 Excel")}}
 "缺失詳情"->{if(current!=null)Column(Modifier.verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("${current["unit"]} ${current["floor"]} · ${current["status"]}");Text(current["description"].orEmpty(),style=MaterialTheme.typography.titleLarge);Text("${current["trade"]} · ${current["vendor"]}");Text("單號：${current["ticket"]}　進入方式：${current["access"]}");Text("歷次修繕紀錄");history.forEach{e->Text("${e.status} / ${e.time}\n${e.note}");e.paths().forEach{id->var b by remember(id){mutableStateOf<ByteArray?>(null)};TextButton(onClick={run{b=withContext(Dispatchers.IO){store.photo(id)?.bytes}}}){Text("查看照片")};b?.let{PhotoView(it)}}};if(current["status"]!="已銷單"){OutlinedTextField(note,{note=it},label={Text("修繕說明")});Row{Button(enabled=!busy,onClick={camera.launch(androidx.core.content.FileProvider.getUriForFile(this@MainActivity, "$packageName.files", File(File(cacheDir,"camera").apply{mkdirs()},"capture.jpg")))}){Text("拍照")};Spacer(Modifier.width(8.dp));Button(enabled=!busy,onClick={gallery.launch("image/*")}){Text("選擇照片")}};Text("已選 ${photos.size} 張");photos.forEach{PhotoView(it)};TextButton(onClick={photos=emptyList()}){Text("清除照片")};Button(enabled=!busy&&photos.isNotEmpty(),onClick={close("已銷單")}){Text("完全修繕銷單")};OutlinedButton(enabled=!busy&&photos.isNotEmpty(),onClick={close("待追蹤")}){Text("部分修繕待追蹤")}}else OutlinedButton(enabled=!busy,onClick={note="重新開啟";close("未銷單")}){Text("重新開啟")}}}
 else->{val field=when(page){"戶別搜尋"->"unit";"工項搜尋"->"trade";else->"vendor"};var filter by remember(page){mutableStateOf("全部")};var status by remember(page){mutableStateOf("全部")};var floor by remember(page){mutableStateOf("全部")};Drop(page,filter,listOf("全部")+data.map{it[field].orEmpty()}.distinct().sorted()){filter=it;floor="全部"};if(field=="unit")Drop("樓層",floor,listOf("全部")+data.filter{filter=="全部"||it[field]==filter}.map{it["floor"].orEmpty()}.distinct().sorted()){floor=it};Drop("狀態",status,listOf("全部","未銷單","待追蹤","已銷單")){status=it};val rows=data.filter{(filter=="全部"||it[field]==filter)&&(status=="全部"||it["status"]==status)&&(floor=="全部"||it["floor"]==floor)};Text("共 ${rows.size} 筆");LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){items(rows,key={it.getValue("id")}){r->ElevatedCard(onClick={run{selected=r.getValue("id");previous=page;refresh();page="缺失詳情"}},modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text("${r["unit"]} ${r["floor"]}　${r["status"]}",color=when(r["status"]){"已銷單"->Color(0xFF00835D);"待追蹤"->Color(0xFFB56A00);else->Color(0xFFB3261E)});Text(r["description"].orEmpty());Text("${r["trade"]} · ${r["vendor"]}")}}}}}
 }
 }}}
