 @Composable fun PhotoView(bytes:ByteArray){val b=remember(bytes){BitmapFactory.decodeByteArray(bytes,0,bytes.size)};if(b!=null)Image(b.asImageBitmap(),contentDescription="修繕照片",modifier=Modifier.fillMaxWidth().height(180.dp))}
 @Composable fun Drop(label:String,value:String,options:List<String>,change:(String)->Unit){var open by remember{mutableStateOf(false)};Box{OutlinedButton(onClick={open=true},modifier=Modifier.fillMaxWidth()){Text("$label：$value ▾")};DropdownMenu(expanded=open,onDismissRequest={open=false}){options.forEach{v->DropdownMenuItem(text={Text(v)},onClick={change(v);open=false})}}}}
 @Composable fun Stats(data:List<Map<String,String>>){val done=data.count{it["status"]=="已銷單"};val pending=data.count{it["status"]=="待追蹤"};Card(Modifier.fillMaxWidth()){Column(Modifier.padding(14.dp)){Text("缺失總數 ${data.size}　已銷單 $done");Text("未銷單 ${data.size-done-pending}　待追蹤 $pending");val rate=if(data.isEmpty())0f else done.toFloat()/data.size;Text("修繕率 %.2f%%".format(rate*100));LinearProgressIndicator(progress={rate},modifier=Modifier.fillMaxWidth())}}}
 fun reports(data:List<Map<String,String>>):Map<String,List<List<String>>>{val done=data.count{it["status"]=="已銷單"};val pending=data.count{it["status"]=="待追蹤"};val header=listOf("戶別","樓層","工項","廠商","缺失","狀態","完成日期","售服單號");val keys=listOf("unit","floor","trade","vendor","description","status","completed","ticket");fun details(rows:List<Map<String,String>>)=listOf(header)+rows.sortedWith(compareBy({it["unit"]},{it["floor"]},{it["trade"]})).map{r->keys.map{r[it].orEmpty()}}
 fun group(k:String)=listOf(listOf("分類","缺失數","銷單數","待追蹤數","修繕率"))+data.groupBy{it[k].orEmpty()}.map{(n,r)->val d=r.count{it["status"]=="已銷單"};listOf(n,r.size.toString(),d.toString(),r.count{it["status"]=="待追蹤"}.toString(),"%.2f%%".format(100.0*d/r.size))}
 return linkedMapOf("修繕統計總覽" to (listOf(listOf("缺失總數",data.size.toString()),listOf("已銷單",done.toString()),listOf("待追蹤",pending.toString()),listOf("修繕率",if(data.isEmpty())"0%" else "%.2f%%".format(100.0*done/data.size)))+data.groupBy{it["trade"].orEmpty()}.entries.sortedByDescending{it.value.size}.take(3).map{listOf(it.key,it.value.size.toString())}),"各戶銷單明細" to details(data.filter{it["status"]=="已銷單"}),"各工項統計" to group("trade"),"各廠商統計" to group("vendor"),"待追蹤明細" to details(data.filter{it["status"]=="待追蹤"}))}
